func merge(ch1, ch2 <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		closed1, closed2 := false, false
		for !closed1 || !closed2 {
			select {
			case v, ok := <-ch1:
				if !ok {
					closed1 = true
					time.Sleep(time.Millisecond) // stop the spin
					continue
				}
				out <- v
			case v, ok := <-ch2:
				if !ok {
					closed2 = true
					time.Sleep(time.Millisecond) // stop the spin
					continue
				}
				out <- v
			}
		}
	}()
	return out
}
